import{_ as i,a as o}from"./chunks/sensor_compass_calibrate_px4.BCkFoXal.js";import{_ as l,c as r,al as a,G as s,B as n,o as c}from"./chunks/framework.D3pXwl8O.js";const v=JSON.parse('{"title":"Калібрування компасу","description":"","frontmatter":{},"headers":[],"relativePath":"uk/config/compass.md","filePath":"uk/config/compass.md"}'),h={name:"uk/config/compass.md"};function p(d,e,m,u,f,g){const t=n("Badge");return c(),r("div",null,[e[0]||(e[0]=a('<h1 id="калібрування-компасу" tabindex="-1">Калібрування компасу <a class="header-anchor" href="#калібрування-компасу" aria-label="Permalink to &quot;Калібрування компасу&quot;">​</a></h1><p>This process calibrates and configures all <a href="./../gps_compass/">magnetometers</a>. <em>QGroundControl</em> will guide you to position the vehicle in a number of set orientations and rotate the vehicle about the specified axis.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>It also auto-detects the compass orientation for external magnetometers (<a href="./../advanced_config/parameter_reference.html#SENS_MAG_AUTOROT">by default</a>). If you have <a href="./../assembly/mount_gps_compass.html#compass-orientation">mounted the compass</a> at a non-standard angle you will need to <a href="./../config/flight_controller_orientation.html#setting-the-compass-orientation">manually set the compass orientation</a> before calibrating.</p></div><h2 id="загальнии-огляд" tabindex="-1">Загальний огляд <a class="header-anchor" href="#загальнии-огляд" aria-label="Permalink to &quot;Загальний огляд&quot;">​</a></h2><p>You will need to calibrate your compass(es) when you first setup your vehicle, and you may need to recalibrate it if the vehicles is ever exposed to a very strong magnetic field, or if it is used in an area with abnormal magnetic characteristics.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Indications of a poor compass calibration include multicopter circling during hover, toilet bowling (circling at increasing radius/spiraling-out, usually constant altitude, leading to fly-way), or veering off-path when attempting to fly straight. <em>QGroundControl</em> should also notify the error <code>mag sensors inconsistent</code>.</p></div><p>The process calibrates all compasses and autodetects the orientation of any external compasses. If any external magnetometers are available, it then disables the internal magnetometers (these are primarily needed for automatic rotation detection of external magnetometers).</p><p>Several types of compass calibration are available:</p><ol><li><a href="#complete-calibration">Complete</a>: This calibration is required after installing the autopilot on an airframe for the first time or when the configuration of the vehicle has changed significantly. Воно компенсує впливи твердого та м&#39;якого заліза, оцінюючи зміщення та коефіцієнт масштабу для кожної вісі.</li><li><a href="#partial-quick-calibration">Partial</a>: This calibration can be performed as a routine when preparing the vehicle for a flight, after changing the payload, or simply when the compass rose seems inaccurate. Цей тип калібрування лише оцінює зміщення для компенсації ефекту твердого заліза.</li><li><a href="#large-vehicle-calibration">Large vehicle</a>: This calibration can be performed when the vehicle is too large or heavy to perform a complete calibration. Цей тип калібрування лише оцінює зміщення для компенсації ефекту твердого заліза.</li></ol><h2 id="виконання-калібрування" tabindex="-1">Виконання калібрування <a class="header-anchor" href="#виконання-калібрування" aria-label="Permalink to &quot;Виконання калібрування&quot;">​</a></h2><h3 id="передумови" tabindex="-1">Передумови <a class="header-anchor" href="#передумови" aria-label="Permalink to &quot;Передумови&quot;">​</a></h3><p>Перед початком калібрування:</p><ol><li>Виберіть місце подалеку від великих металевих об&#39;єктів або магнітних полів.</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Metal is not always obvious! Уникайте калібрування на верхній частині офісного столу (часто містять металеві пластины) або поруч з транспортним засобом. Калібрування може бути навіть уражено, якщо ви стоїте на бетонній плиті з нерівномірним розподілом арматури.</p></div><ol start="2"><li>Підключайтесь за допомогою телеметричного радіо, а не через USB, якщо це взагалі можливо. USB потенційно може викликати значне магнітне втручання.</li><li>If using an external compass (or a combined GPS/compass module), make sure it is <a href="./../assembly/mount_gps_compass.html">mounted</a> as far as possible from other electronics in order to reduce magnetic interference, and in a <em>supported orientation</em>.</li></ol><h3 id="повне-калібрування" tabindex="-1">Повне калібрування <a class="header-anchor" href="#повне-калібрування" aria-label="Permalink to &quot;Повне калібрування&quot;">​</a></h3><p>Калібрування включає наступні кроки:</p><ol><li><p>Start <em>QGroundControl</em> and connect the vehicle.</p></li><li><p>Select <strong>&quot;Q&quot; icon &gt; Vehicle Setup &gt; Sensors</strong> (sidebar) to open <em>Sensor Setup</em>.</p></li><li><p>Click the <strong>Compass</strong> sensor button.</p></li></ol><p><img src="'+i+'" alt="Select Compass calibration PX4"></p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>You should already have set the <a href="./../config/flight_controller_orientation.html">Autopilot Orientation</a>. Якщо ні, ви також можете встановити це тут.</p></div><ol start="4"><li><p>Click <strong>OK</strong> to start the calibration.</p></li><li><p>Розмістіть транспортний засіб у будь-якому з показаних червоних орієнтацій (неповний) та утримуйте його нерухомим. Після запиту (орієнтаційне зображення стає жовтим) обертайте транспортний засіб навколо вказаної вісі в одному або обох напрямках. Після завершення калібрування для поточного орієнтації пов&#39;язане зображення на екрані стане зеленим.</p></li></ol><p><img src="'+o+'" alt="Compass calibration steps on PX4"></p><ol start="6"><li>Повторіть процес калібрування для всіх орієнтацій автомобіля.</li></ol><p>Once you&#39;ve calibrated the vehicle in all the positions <em>QGroundControl</em> will display <em>Calibration complete</em> (all orientation images will be displayed in green and the progress bar will fill completely). Ви можете потім перейти до наступного сенсора.</p><h3 id="часткова-швидка-калібрування" tabindex="-1">Часткова &quot;Швидка&quot; Калібрування <a class="header-anchor" href="#часткова-швидка-калібрування" aria-label="Permalink to &quot;Часткова &quot;Швидка&quot; Калібрування&quot;">​</a></h3><p>Ця калібровка схожа на відому калібровку компасу у вигляді восьмірки, виконану на смартфоні:</p><ol><li>Утримуйте транспортний засіб перед собою та випадковим чином виконуйте часткові обертання по всіх його осях. 2-3 коливань на кут близько 30 градусів у кожному напрямку зазвичай достатньо.</li><li>Зачекайте, поки оцінка заголовку стабілізується, і перевірте, що компас вказує в правильному напрямку (це може зайняти кілька секунд).</li></ol><p>Примітки:</p><ul><li>Немає можливості початку/зупинки для цього типу калібрування (алгоритм працює безперервно, коли транспортний засіб роззброєний).</li><li>Калібрування негайно застосовується до даних (перезавантаження не потрібно), але зберігається в параметрах калібрування лише після відброшення транспортного засобу (калібрування втрачається, якщо між калібруванням і вимкненням не виконана послідовність увімкнення/вимкнення).</li><li>Амплітуда та швидкість часткових обертань, виконаних на кроці 1, можуть впливати на якість калібрування. Найчастіше вище зазначені поради виявляються досить ефективними.</li></ul><h3 id="large-vehicle-calibration" tabindex="-1">Large Vehicle Calibration <a class="header-anchor" href="#large-vehicle-calibration" aria-label="Permalink to &quot;Large Vehicle Calibration&quot;">​</a></h3>',30)),s(t,{type:"tip",text:"PX4 v1.15"}),e[1]||(e[1]=a('<p>This calibration process leverages external knowledge of vehicle&#39;s orientation and location, and a World Magnetic Model (WMM) to calibrate the hard iron biases.</p><ol><li>Ensure GNSS Fix. This is required to find the expected Earth magnetic field in WMM tables.</li><li>Align the vehicle to face True North. Be as accurate as possible for best results.</li><li>Open the <a href="https://docs.qgroundcontrol.com/master/en/qgc-user-guide/analyze_view/mavlink_console.html" target="_blank" rel="noreferrer">QGroundControl MAVLink Console</a> and send the following command:</li></ol><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">commander</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> calibrate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mag</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> quick</span></span></code></pre></div><p>Примітки:</p><ul><li>This method is specifically designed for vehicles where full rotation is impractical or impossible. If full rotation is possible, use the <a href="#complete-calibration">complete calibration</a> instead.</li><li>The vehicle doesn&#39;t need to be exactly levelled as this is automatically compensated using the tilt estimate.</li><li>This calibration can also be triggered using the MAVLink command <a href="https://mavlink.io/en/messages/common.html#MAV_CMD_FIXED_MAG_CAL_YAW" target="_blank" rel="noreferrer">MAV_CMD_FIXED_MAG_CAL_YAW</a>.</li></ul><h2 id="перевірка" tabindex="-1">Перевірка <a class="header-anchor" href="#перевірка" aria-label="Permalink to &quot;Перевірка&quot;">​</a></h2><p>Після завершення калібрування перевірте, щоб індикатор напрямку та напрямок стрілки на карті були стабільними і відповідали орієнтації транспортного засобу при його повороті, наприклад, на головні сторони.</p><h2 id="додаткова-калібрування-конфігурація" tabindex="-1">Додаткова калібрування/конфігурація <a class="header-anchor" href="#додаткова-калібрування-конфігурація" aria-label="Permalink to &quot;Додаткова калібрування/конфігурація&quot;">​</a></h2><p>The process above will autodetect, <a href="./../advanced_config/parameter_reference.html#SENS_MAG_AUTOROT">set default rotations</a>, calibrate, and prioritise, all available magnetometers. If external magnetometers are available, internal magnetometers are disabled.</p><p>Додаткова конфігурація компаса, як правило, не повинна бути потрібною.</p><h3 id="enable-disable-a-compass" tabindex="-1">Enable/Disable a Compass <a class="header-anchor" href="#enable-disable-a-compass" aria-label="Permalink to &quot;Enable/Disable a Compass&quot;">​</a></h3><p>While no further configuration should be <em>required</em>, developers who wish to disable/enable compasses for any reason, such as testing, can do so using the compass parameters. These are prefixed with <a href="./../advanced_config/parameter_reference.html#CAL_MAG0_ID">CAL_MAGx_</a> (where <code>x=0-3</code>):</p><ul><li><a href="./../advanced_config/parameter_reference.html#CAL_MAG0_ROT">CAL_MAGn_ROT</a> can be used to determine which compasses are internal. A compass is internal if <code>CAL_MAGn_ROT==1</code>.</li><li><a href="./../advanced_config/parameter_reference.html#CAL_MAG0_PRIO">CAL_MAGx_PRIO</a> sets the relative compass priority and can be used to disable a compass.</li></ul><h2 id="відлагодження" tabindex="-1">Відлагодження <a class="header-anchor" href="#відлагодження" aria-label="Permalink to &quot;Відлагодження&quot;">​</a></h2><p>Raw comparison data for magnetometers (in fact, for all sensors) can be logged by setting <a href="./../advanced_config/parameter_reference.html#SDLOG_MODE">SDLOG_MODE=1</a> and <a href="./../advanced_config/parameter_reference.html#SDLOG_PROFILE">SDLOG_PROFILE=64</a>. See <a href="./../dev_log/logging.html">Logging</a> for more information.</p><h2 id="подальша-інформація" tabindex="-1">Подальша інформація <a class="header-anchor" href="#подальша-інформація" aria-label="Permalink to &quot;Подальша інформація&quot;">​</a></h2><ul><li><a href="./../gps_compass/">Peripherals &gt; GPS &amp; Compass</a></li><li><a href="./../assembly/">Basic Assembly</a> (setup guides for each flight controller)</li><li><a href="./../advanced_config/compass_power_compensation.html">Compass Power Compensation</a> (Advanced Configuration)</li><li><a href="https://docs.qgroundcontrol.com/master/en/qgc-user-guide/setup_view/sensors_px4.html#compass" target="_blank" rel="noreferrer">QGroundControl User Guide &gt; Sensors</a></li><li><a href="https://youtu.be/91VGmdSlbo4?t=2m38s" target="_blank" rel="noreferrer">PX4 Setup Video - @2m38s</a> (Youtube)</li></ul>',17))])}const k=l(h,[["render",p]]);export{v as __pageData,k as default};
